import hashlib
import json
import time

class Block:
    def __init__(self, index, transactions, previous_hash, nonce=0):
        self.index = index
        self.timestamp = time.time()
        self.transactions = transactions
        self.previous_hash = previous_hash
        self.nonce = nonce
        self.hash = self.compute_hash()

    def compute_hash(self):
        block_data = json.dumps({
            "index": self.index,
            "timestamp": self.timestamp,
            "transactions": self.transactions,
            "previous_hash": self.previous_hash,
            "nonce": self.nonce,
        }, sort_keys=True)
        return hashlib.sha256(block_data.encode()).hexdigest()

class Blockchain:
    def __init__(self, difficulty=4):
        self.difficulty = difficulty
        self.chain = [self.create_genesis_block()]
        self.pending = []

    def create_genesis_block(self):
        return Block(0, [], "0" * 64)

    def add_transaction(self, sender, recipient, amount):
        self.pending.append({"from": sender, "to": recipient, "amount": amount})

    def mine_block(self):
        if not self.pending:
            return None

        block = Block(
            index=len(self.chain),
            transactions=self.pending,
            previous_hash=self.chain[-1].hash,
        )

        target = "0" * self.difficulty
        while not block.hash.startswith(target):
            block.nonce += 1
            block.hash = block.compute_hash()

        self.chain.append(block)
        self.pending = []
        return block

    def is_valid(self):
        for i in range(1, len(self.chain)):
            curr = self.chain[i]
            prev = self.chain[i - 1]
            if curr.hash != curr.compute_hash():
                return False
            if curr.previous_hash != prev.hash:
                return False
        return True

bc = Blockchain(difficulty=3)
bc.add_transaction("Alice", "Bob", 10)
bc.add_transaction("Bob", "Carol", 5)
block = bc.mine_block()
print(f"Block {block.index}: {block.hash[:16]}... ({block.nonce} iterations)")
print(f"Chain valid: {bc.is_valid()}")

import requests
from bs4 import BeautifulSoup
import time
import random
import hashlib
from urllib.parse import urljoin

class ProductionScraper:
    def __init__(self):
        self.session = requests.Session()
        self.user_agents = [
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64)...",
            "Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7)...",
        ]
        self.delay_range = (1, 3)

    def get_page(self, url, retries=3):
        for attempt in range(retries):
            try:
                self.session.headers["User-Agent"] = random.choice(self.user_agents)
                time.sleep(random.uniform(*self.delay_range))

                resp = self.session.get(url, timeout=10)
                if resp.status_code == 429:
                    wait = int(resp.headers.get("Retry-After", 60))
                    print(f"Rate limited, waiting {wait}s")
                    time.sleep(wait)
                    continue

                resp.raise_for_status()
                return BeautifulSoup(resp.text, "html.parser")
            except requests.RequestException as e:
                print(f"Attempt {attempt + 1} failed: {e}")
                time.sleep(2 ** attempt)
        return None

    def extract_links(self, soup, base_url):
        links = set()
        for a in soup.find_all("a", href=True):
            links.add(urljoin(base_url, a["href"]))
        return links

    def extract_table(self, soup, table_selector="table"):
        results = []
        for table in soup.select(table_selector):
            headers = [th.text.strip() for th in table.find_all("th")]
            for row in table.find_all("tr")[1:]:
                cols = [td.text.strip() for td in row.find_all("td")]
                if cols:
                    results.append(dict(zip(headers, cols)) if headers else cols)
        return results

    def detect_content_hash(self, soup):
        text = soup.get_text(strip=True)
        return hashlib.md5(text.encode()).hexdigest()

