from abc import ABC, abstractmethod
from typing import Any

# Factory pattern
class Serializer(ABC):
    @abstractmethod
    def serialize(self, data: dict) -> str: ...

class JSONSerializer(Serializer):
    def serialize(self, data):
        import json
        return json.dumps(data, indent=2)

class CSVSerializer(Serializer):
    def serialize(self, data):
        if isinstance(data, list) and data:
            headers = data[0].keys()
            lines = [",".join(headers)]
            for row in data:
                lines.append(",".join(str(row[h]) for h in headers))
            return "\n".join(lines)
        return ""

def get_serializer(fmt: str) -> Serializer:
    factories = {"json": JSONSerializer, "csv": CSVSerializer}
    return factories[fmt]()

data = [{"name": "Alice", "age": 30}, {"name": "Bob", "age": 25}]
print(get_serializer("json").serialize(data))

# Chain of Responsibility
class Handler:
    def __init__(self):
        self._next = None

    def set_next(self, handler):
        self._next = handler
        return handler

    def handle(self, request):
        if self._next:
            return self._next.handle(request)
        return None

class AuthHandler(Handler):
    def handle(self, request):
        if not request.get("token"):
            return "Auth failed: no token"
        print("Auth passed")
        return super().handle(request)

class RateLimitHandler(Handler):
    def handle(self, request):
        if request.get("count", 0) > 100:
            return "Rate limit exceeded"
        print("Rate limit passed")
        return super().handle(request)

class FinalHandler(Handler):
    def handle(self, request):
        return "Request processed successfully"

chain = AuthHandler()
chain.set_next(RateLimitHandler()).set_next(FinalHandler())
print(chain.handle({"token": "abc", "count": 50}))

# WSGI application (synchronous)
class WSGIApp:
    def __init__(self):
        self.routes = {}

    def route(self, path):
        def decorator(func):
            self.routes[path] = func
            return func
        return decorator

    def __call__(self, environ, start_response):
        path = environ.get("PATH_INFO", "/")
        method = environ.get("REQUEST_METHOD", "GET")

        handler = self.routes.get(path)
        if handler:
            status = "200 OK"
            body = handler(environ).encode()
        else:
            status = "404 Not Found"
            body = b"Not Found"

        headers = [("Content-Type", "text/plain"), ("Content-Length", str(len(body)))]
        start_response(status, headers)
        return [body]

